    def probe_once(self, target="example.com:443"):
        host, _, port = target.partition(":")
        for u in self.upstreams:
            if not u.enabled:
                continue
            if u.breaker.state() == CircuitBreaker.OPEN:
                continue
            if not u.breaker.allow():
                continue
            deadline = time.monotonic() + self.deadline_s
            t0 = time.monotonic()
