class TestHealthTracker(unittest.TestCase):
    def test_neutral_when_empty(self):
        t = HealthTracker(**SCORING)
        self.assertEqual(t.score(), 50.0)

    def test_score_math(self):
        t = HealthTracker(**SCORING)
        for _ in range(10):
            t.record(True, 100, "probe")
        # rate 1.0, avg 0.1s -> factor 1/(1+0.02)
        self.assertAlmostEqual(t.score(), 100 * 1 / 1.02, places=1)
        for _ in range(10):
            t.record(False, 100, "probe")
        self.assertAlmostEqual(t.score(), 100 * 0.5 / 1.02, places=1)

    def test_window_trims_old_events(self):
        t = HealthTracker(window_events=50, window_s=300, neutral_score=50)
        old = time.time() - 10000
        for _ in range(5):
            t.record(False, 10, "probe", ts=old)
        self.assertEqual(t.score(), 50.0)  # all pruned -> neutral

