class EchoProxyServer(threading.Thread):
    """Minimal working CONNECT proxy: answers 200, then echoes bytes back."""
    def __init__(self):
        super().__init__(daemon=True)
        self.sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self.sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        self.sock.bind(("127.0.0.1", 0))
        self.sock.listen(16)
        self.port = self.sock.getsockname()[1]

    def run(self):
        while True:
            try:
                c, _ = self.sock.accept()
            except OSError:
                return
            threading.Thread(target=self._handle, args=(c,),
                             daemon=True).start()

    def _handle(self, c):
        try:
            read_headers(c, time.monotonic() + 10)
            c.sendall(b"HTTP/1.1 200 Connection Established\r\n\r\n")
            while True:
                data = c.recv(4096)
                if not data:
                    break
                c.sendall(data)
        except Exception:
            pass
        finally:
            c.close()

