}
_QR_M_BYTE_CAPACITY = {1: 14, 2: 26, 3: 42, 4: 62, 5: 84,
                       6: 106, 7: 122, 8: 152, 9: 180, 10: 213}
_QR_ALIGN = {1: [], 2: [6, 18], 3: [6, 22], 4: [6, 26], 5: [6, 30],
             6: [6, 34], 7: [6, 22, 38], 8: [6, 24, 42],
             9: [6, 26, 46], 10: [6, 28, 50]}
