def _data_codewords(data, version):
    ec_len, groups = _QR_M_BLOCKS[version]
    total_data = sum(n * d for n, d in groups)
    bits = []

    def push(val, nbits):
        for i in range(nbits - 1, -1, -1):
            bits.append((val >> i) & 1)

    push(0b0100, 4)                                # byte mode
    push(len(data), 8 if version < 10 else 16)     # length
    for b in data:
        push(b, 8)
    cap_bits = total_data * 8
    bits.extend([0] * min(4, cap_bits - len(bits)))  # terminator
    while len(bits) % 8:
        bits.append(0)
    out = bytearray()
    for i in range(0, len(bits), 8):
        byte = 0
        for bit in bits[i:i + 8]:
            byte = (byte << 1) | bit
        out.append(byte)
    pads = (0xEC, 0x11)
    k = 0
    while len(out) < total_data:
        out.append(pads[k % 2])
        k += 1
    return bytes(out)

