def _interleave(data, version):
    ec_len, groups = _QR_M_BLOCKS[version]
    blocks, ecs = [], []
    pos = 0
    for count, dcw in groups:
        for _ in range(count):
            chunk = data[pos:pos + dcw]
            pos += dcw
            blocks.append(chunk)
            ecs.append(_rs_encode(chunk, ec_len))
    out = bytearray()
    for i in range(max(len(b) for b in blocks)):
        for b in blocks:
            if i < len(b):
                out.append(b[i])
    for i in range(ec_len):
        for e in ecs:
            out.append(e[i])
    return bytes(out)

