def _qr_matrix(data, _return_fn=False):
    """Return (version, size, matrix, mask) with matrix[r][c] True = dark.
    _return_fn=True appends the function-module map (test extraction)."""
    if isinstance(data, str):
        data = data.encode("utf-8")
    version = next((v for v in range(1, 11)
                    if len(data) <= _QR_M_BYTE_CAPACITY[v]), None)
    if version is None:
        raise ValueError("payload too long for QR versions 1-10 (EC M)")
    codewords = _interleave(_data_codewords(data, version), version)
