# genesis-os/cody/qualify_harness.py — module (no paired test file in tree) (chunk 3)
def chat(base, model, prompt, extra):
    body = {"model": model,
            "messages": [{"role": "user", "content": prompt}],
            "temperature": 0, "max_tokens": 700}
    if extra:
        body.update(extra)
    t0 = time.time()
    rc, code, payload = curl_post(base.rstrip("/") + "/chat/completions", body)
    lat = int((time.time() - t0) * 1000)
    if rc != 0 or code in ("000", ""):
        return {"ok": False, "error": "TIMEOUT" if rc == 28 else "CONN",
                "http": code, "latency_ms": lat}
    try:
        d = json.loads(payload)
    except Exception:
        return {"ok": False, "error": "BADJSON", "http": code,
                "latency_ms": lat, "snippet": payload[:200]}
    if code != "200":
        return {"ok": False, "error": "HTTP_" + code, "http": code,
                "latency_ms": lat,
                "snippet": json.dumps(d)[:200]}
    ch = (d.get("choices") or [{}])[0]
    msg = ch.get("message") or {}
    content = msg.get("content") or ch.get("text") or ""
    usage = d.get("usage") or {}
    return {"ok": True, "http": code, "latency_ms": lat,
            "returned_model": d.get("model"),
            "content": content,
            "tokens": usage.get("total_tokens")}

