def check_t2(content):
    code = content or ""
    if "```" in code:
        parts = code.split("```")
        code = max(parts, key=len) if len(parts) > 1 else code
        code = code.replace("python", "", 1).strip() if code.startswith("python") else code
    if "def clamp01" not in code:
        return False, "no clamp01 def"
    for bad in ("import ", "open(", "os.", "sys.", "subprocess", "eval(", "exec("):
        if bad in code:
            return False, "unsafe content: " + bad
    test = code + """

assert clamp01(0.5) == 0.5, clamp01(0.5)
assert clamp01(-2) == 0.0, clamp01(-2)
assert clamp01(5) == 1.0, clamp01(5)
assert clamp01(0) == 0.0
print("T2PASS")
"""
    with tempfile.NamedTemporaryFile("w", suffix=".py", delete=False) as f:
        f.write(test)
        path = f.name
    try:
        p = subprocess.run([sys.executable, path], capture_output=True,
                           text=True, timeout=8)
        return ("T2PASS" in p.stdout), (p.stdout + p.stderr)[:160].strip()
    except Exception as e:
        return False, "exec error: " + str(e)[:120]
    finally:
        try:
            os.unlink(path)
        except OSError:
            pass
